steps.sampleSolution:
def explorar_bfs(grafo, inicio):
    fila = deque([inicio])
    visitados = {inicio}
    while fila:
        atual = fila.popleft()
        for viz in grafo[atual]:
            if viz not in visitados:
                visitados.add(viz)
                fila.append(viz)
    return visitados
